// ▼▼ 여기에 네이버 개발자센터에서 발급받은 값을 붙여 넣으세요 (이 파일을 남에게 공유하기 전에 지우세요) ▼▼
const CLIENT_ID = 'mx10zsn9yk';
const CLIENT_SECRET = 'BQ7xrx99pvkySUqQBuPIekSQ32bgd0b7rpdZDOos';
// ▲▲▲
const DISPLAY = 20;   // 검색어 1개당 가져올 글 수 (최대값은 공식 문서 확인)
const SORT = 'sim';   // sim=정확도순, date=최신순

const KW = [["전원 관련", "에어컨 전원이 안 켜져요"], ["전원 관련", "에어컨 켜자마자 꺼져요"], ["전원 관련", "LG 에어컨 전원 저절로 꺼짐"], ["전원 관련", "에어컨 리모컨 눌러도 반응 없어요"], ["전원 관련", "에어컨 전원 깜빡거려요"], ["냉방 관련", "LG 에어컨 안 시원해요"], ["냉방 관련", "에어컨 바람은 나오는데 차갑지 않아요"], ["냉방 관련", "에어컨 18도인데도 안 시원"], ["냉방 관련", "에어컨 켜도 미지근한 바람"], ["냉방 관련", "에어컨 냉방 약해졌어요"], ["에러코드", "LG 에어컨 CH 에러코드"], ["에러코드", "LG 에어컨 E1 표시"], ["에러코드", "에어컨 표시창에 숫자 뜨는데 뭐예요"], ["에러코드", "LG 에어컨 에러 코드 해결"], ["에러코드", "에어컨 CH05 CH38 뜸"], ["누수 관련", "LG 에어컨 물이 떨어져요"], ["누수 관련", "에어컨 실내기에서 물 샘"], ["누수 관련", "에어컨 벽에 물 흘러요"], ["누수 관련", "에어컨 배수 안 돼요"], ["누수 관련", "에어컨 물방울 떨어짐"], ["냄새 관련", "LG 에어컨 냄새 나요"], ["냄새 관련", "에어컨 켜면 쉰내 곰팡이 냄새"], ["냄새 관련", "에어컨 냄새 제거 방법"], ["냄새 관련", "에어컨 처음 켤 때 퀴퀴한 냄새"], ["냄새 관련", "에어컨 탄내 나요"], ["실외기", "에어컨 실외기 소리 너무 커요"], ["실외기", "실외기 안 돌아가요"], ["실외기", "에어컨 실외기 진동 심해요"], ["실외기", "실외기 팬이 안 돌아요"], ["실외기", "에어컨 실외기 연기 냄새"], ["기능 표시", "에어컨 램프 깜빡여요"], ["기능 표시", "에어컨 LED 불빛 깜빡임 의미"], ["기능 표시", "에어컨 표시등 빨간불"], ["기능 표시", "에어컨 불빛 색깔 의미"], ["기능 표시", "에어컨 램프 두 개 동시에 깜빡"], ["작동 관련", "에어컨 작동 중에 소리 나요"], ["작동 관련", "에어컨 알아서 꺼졌다 켜졌다"], ["작동 관련", "에어컨 설정온도 안 맞아요"], ["작동 관련", "에어컨 풍량 조절 안 돼요"], ["작동 관련", "에어컨 타이머 예약 사용법"], ["리모컨", "LG 에어컨 리모컨 안 먹어요"], ["리모컨", "에어컨 리모컨 건전지 교체했는데 안 돼요"], ["리모컨", "에어컨 리모컨 사용법 모르겠어요"], ["리모컨", "에어컨 리모컨 표시 의미"], ["리모컨", "LG 에어컨 리모컨 분실 새로"], ["난방 관련", "에어컨 난방 안 돼요"], ["난방 관련", "에어컨 히터 모드 찬바람"], ["난방 관련", "에어컨 난방 설정 방법"], ["난방 관련", "에어컨 난방 성에 제거 중"], ["난방 관련", "에어컨 겨울에 따뜻한 바람 안 나옴"], ["필터/청소", "LG 에어컨 필터 청소 방법"], ["필터/청소", "에어컨 필터 어디 있어요"], ["필터/청소", "에어컨 필터 교체 시기"], ["필터/청소", "에어컨 청소 직접 하는 법"], ["필터/청소", "에어컨 극세필터 세척"], ["스마트케어/인공지능", "LG ThinQ 에어컨 연결 안 돼요"], ["스마트케어/인공지능", "휘센 에어컨 와이파이 연결"], ["스마트케어/인공지능", "에어컨 스마트폰으로 켜는 법"], ["스마트케어/인공지능", "ThinQ 앱 에어컨 등록 안 됨"], ["스마트케어/인공지능", "에어컨 음성인식 사용법"], ["제습", "에어컨 제습 모드 사용법"], ["제습", "제습 모드 전기세"], ["제습", "에어컨 제습하면 더워요"], ["제습", "에어컨 제습 모드 물 안 나와요"], ["제습", "에어컨 제습 냉방 차이"], ["설치 환경", "에어컨 설치 위치 문제"], ["설치 환경", "에어컨 이전설치 비용"], ["설치 환경", "에어컨 배관 길이 추가 비용"], ["설치 환경", "에어컨 설치 후 소음"], ["설치 환경", "에어컨 이사 철거 설치"]];
return KW.map(([symptom, q]) => ({ json: { symptom, query: q, display: DISPLAY, sort: SORT, cid: CLIENT_ID, secret: CLIENT_SECRET } }));

// 지식인 검색 결과 → 질문 CSV (UTF-8 BOM). 라벨 컬럼은 비워 두고, 규칙으로 구분 가능한 것만 초기값을 채움
const metas = $('검색어 목록').all();
const decode = s => String(s || '').replace(/<[^>]+>/g, '').replace(/&quot;/g, '"').replace(/&apos;|&#39;/g, "'")
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&nbsp;/g, ' ').replace(/&#(\d+);/g, (_, n) => String.fromCharCode(+n))
  .replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim();
const TRIED = /(해봤|해 봤|시도|했는데|했는데도|교체했|청소했|껐다 켰|재부팅|그대로|여전히|계속)/;
const CALL = /(서비스센터|서비스 센터|AS|A\/S|수리 ?기사|기사님|방문 ?(수리|점검)|고객센터|상담원|출장|수리 ?(비|비용)|수리 ?받)/i;
const PROXY = /(부모님|어머니|아버지|엄마|아빠|어르신|할머니|할아버지|시어머니|친정)/;
const esc = v => '"' + String(v ?? '').replace(/"/g, '""') + '"';
const today = new Date().toISOString().slice(0, 10);
const HEAD = ['출처','원문URL','작성일','수집일','검색어','검색증상(초기값)','질문제목','질문원문(요약)','LG언급','제품유형','증상분류','질문유형','스스로해결범위','가이드존재','매칭가이드URL','매칭신뢰도','시도여부(초기값)','상담요청신호(초기값)','가이드해결책이미_답변됨','대리질문(초기값)','고령층표현','사람검수여부','검수결과'];
const seen = new Set(); const rows = []; let apiErr = 0;
$input.all().forEach((it, i) => {
  const m = metas[i].json; const items = it.json && it.json.items;
  if (!Array.isArray(items)) { apiErr++; return; }
  for (const r of items) {
    const link = String(r.link || '').trim(); if (!link || seen.has(link)) continue;
    const title = decode(r.title), desc = decode(r.description), text = title + ' ' + desc;
    if (!/(에어컨|휘센)/.test(text)) continue;       // 에어컨과 무관한 글 제외
    seen.add(link);
    rows.push(['네이버 지식인', link, '', today, m.query, m.symptom, title, desc, /(LG|엘지|휘센|씽큐|ThinQ)/i.test(text) ? 'Y' : 'N',
      '', '', '', '', '', '', '', TRIED.test(text) ? 'Y' : '', CALL.test(text) ? 'Y' : '', '', PROXY.test(text) ? 'Y' : '', '', '', '']);
  }
});
const csv = '﻿' + [HEAD, ...rows].map(r => r.map(esc).join(',')).join('\r\n');
const binary = { data: await this.helpers.prepareBinaryData(Buffer.from(csv, 'utf8'), 'naver_kin_questions.csv', 'text/csv') };
return [{ json: { 수집건수: rows.length, 검색어수: metas.length, API오류응답수: apiErr, 파일명: 'naver_kin_questions.csv' }, binary }];
